shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
+++ b/src/test/java/io/reactivex/rxjava3/internal/operators/observable/ObservableSwitchTest.java
@@ -1400,6 +1400,34 @@
     }

     @Test
+    public void disposeBeforeInnerOnSubscribe() {
+        for (boolean delayErrors : new boolean[] { false, true }) {
+            PublishSubject<Integer> ps = PublishSubject.create();
+            PublishSubject<Integer> inner = PublishSubject.create();
+            TestObserver<Integer> to = new TestObserver<>();
+
+            Function<Integer, Observable<Integer>> mapper = v -> inner
+                    .doOnSubscribe(d -> to.dispose())
+                    .scan(0, (a, b) -> a + b);
+
+            if (delayErrors) {
+                ps.switchMapDelayError(mapper).subscribe(to);
+            } else {
+                ps.switchMap(mapper).subscribe(to);
+            }
+
+            ps.onNext(1);
+
+            to.assertEmpty();
+            assertTrue(to.isDisposed());
+            assertFalse(ps.hasObservers());
+            assertFalse(inner.hasObservers());
+        }
+    }
+
+    @Test
     public void cancellationShouldTriggerInnerCancellationRace() throws Throwable {
         AtomicInteger outer = new AtomicInteger();
         AtomicInteger inner = new AtomicInteger();
PATCH
./gradlew --offline test --tests io.reactivex.rxjava3.internal.operators.observable.ObservableSwitchTest.disposeBeforeInnerOnSubscribe

